    {"id": "cut_pacing.silence_remove", "category": "cut_pacing", "name": "Remove dead air", "detector": {"kind": "silence", "args": {"min_gap_ms": "{{max_gap_ms}}"}}, "effect": {"op": "cut", "args": {"keep_ms": "{{keep_ms}}", "crossfade_ms": 30}}, "params": {"max_gap_ms": {"type": "integer", "default": 450, "min": 200, "max": 2000, "description": "Silences at least this long are cut"}, "keep_ms": {"type": "integer", "default": 160, "min": 0, "max": 600, "description": "Breathing room kept around each cut"}}, "applies_to": ["talking_head", "ad_ugc", "podcast_clip", "long_form", "screen_demo"], "source": "house", "default_on": true, "rationale": "Dead air is the first thing viewers scroll past; keeping a short pause preserves natural rhythm."},
    {"id": "cut_pacing.filler_remove", "category": "cut_pacing", "name": "Remove filler words", "detector": {"kind": "filler_word", "args": {"words": "{{words}}"}}, "effect": {"op": "cut", "args": {"keep_ms": 40, "crossfade_ms": 30, "min_cut_ms": 80}}, "params": {"words": {"type": "string[]", "default": ["um", "uh", "erm", "hmm"], "description": "Per-language filler list. Add 'like' or 'you know' only if the speaker overuses them."}}, "applies_to": ["talking_head", "ad_ugc", "podcast_clip", "long_form"], "source": "house", "default_on": true, "rationale": "Fillers read as unprepared; cutting them is the cheapest perceived-quality gain."},
    {"id": "cut_pacing.breath_remove", "category": "cut_pacing", "name": "Trim audible breaths", "detector": {"kind": "silence", "args": {"min_gap_ms": 250}}, "effect": {"op": "cut", "args": {"keep_ms": 220, "crossfade_ms": 40}}, "params": {}, "applies_to": ["talking_head", "ad_ugc"], "conflicts_with": ["cut_pacing.silence_remove"], "source": "house", "rationale": "Softer alternative to silence_remove for calm formats: shortens breath gaps instead of removing them."},
    {"id": "cut_pacing.jump_cut_sentence", "category": "cut_pacing", "name": "Jump cut on sentence boundaries", "detector": {"kind": "sentence_boundary"}, "effect": {"op": "crossfade", "args": {"ms": 30}}, "params": {"max_shot_ms": {"type": "integer", "default": 6000, "min": 2000, "max": 15000}}, "applies_to": ["talking_head", "podcast_clip", "long_form"], "source": "house", "default_on": true, "rationale": "Cuts on sentence ends feel invisible; cuts mid-sentence feel like mistakes (rule F1)."},
    {"id": "cut_pacing.dead_air_head_tail", "category": "cut_pacing", "name": "Trim dead air at start and end", "detector": {"kind": "silence", "args": {"min_gap_ms": 300}}, "effect": {"op": "cut", "args": {"keep_ms": 60, "crossfade_ms": 20}}, "params": {}, "applies_to": ["talking_head", "ad_ugc", "screen_demo", "podcast_clip", "long_form"], "source": "house", "default_on": true, "rationale": "A video must start on the first word; the hook clock starts at frame 0."},
    {"id": "cut_pacing.max_shot_length", "category": "cut_pacing", "name": "Max single shot length by format", "detector": {"kind": "sentence_boundary"}, "effect": {"op": "crossfade", "args": {"ms": 30}}, "params": {"talking_head_ms": {"type": "integer", "default": 5000}, "ad_ugc_ms": {"type": "integer", "default": 2500}, "long_form_ms": {"type": "integer", "default": 12000}}, "applies_to": ["talking_head", "ad_ugc", "long_form"], "requires": ["zoom_framing.alternate_crop_ab"], "source": "house", "rationale": "When no cut is available, a visual change (punch-in or crop change) must happen within the max shot length (rule P1)."},
    {"id": "cut_pacing.hook_first", "category": "cut_pacing", "name": "Hook-first reorder", "detector": {"kind": "always"}, "effect": {"op": "reorder", "args": {"beat": "hook"}}, "params": {}, "applies_to": ["talking_head", "ad_ugc", "podcast_clip", "long_form"], "source": "house", "rationale": "Open on the strongest self-contained line; keep or drop the original intro (rule F5)."},
    {"id": "cut_pacing.speed_up_slow_sections", "category": "cut_pacing", "name": "Speed up slow sections slightly", "detector": {"kind": "topic_change", "args": {"min_gap_ms": 1200}}, "effect": {"op": "speed", "args": {"speed": "{{speed}}"}}, "params": {"speed": {"type": "number", "default": 1.05, "min": 1.0, "max": 1.15}}, "applies_to": ["talking_head", "long_form"], "source": "house", "rationale": "A 5% speed-up is below the threshold most viewers notice and recovers time without cuts."}
  ]
}

